/// Key event action.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum KeyAction {
    Release = 0,
    Press = 1,
    Repeat = 2,
}

impl KeyAction {
    /// Every variant, in numbering order.
    pub const ALL: [KeyAction; 3] = [KeyAction::Release, KeyAction::Press, KeyAction::Repeat];
}

impl TryFrom<u32> for KeyAction {
    type Error = u32;
    fn try_from(v: u32) -> Result<Self, u32> {
        match v {
            0 => Ok(KeyAction::Release),
            1 => Ok(KeyAction::Press),
            2 => Ok(KeyAction::Repeat),
            _ => Err(v),
        }
    }
}

