bitflags::bitflags! {
    /// Keyboard modifiers.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub struct Mods: u16 {
        const SHIFT = 0x0001;
        const ALT = 0x0004;
        const CTRL = 0x0002;
        const SUPER = 0x0008;
        const CAPS_LOCK = 0x0010;
        const NUM_LOCK = 0x0020;
        const SHIFT_SIDE = 0x0040;
        const ALT_SIDE = 0x0100;
        const CTRL_SIDE = 0x0080;
        const SUPER_SIDE = 0x0200;
    }

    /// Kitty keyboard protocol flags.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub struct KittyKeyFlags: u8 {
        const DISABLED = 0x00;
        const DISAMBIGUATE = 0x01;
        const REPORT_EVENTS = 0x02;
        const REPORT_ALTERNATES = 0x04;
        const REPORT_ALL = 0x08;
        const REPORT_ASSOCIATED = 0x10;
        const ALL = 0x1f;
    }
}
